def can_complete(row, tenant, owner, fence, now):
    if not isinstance(row, dict):
        return False
    if not isinstance(fence, int) or isinstance(fence, bool):
        return False
    if not isinstance(now, int) or isinstance(now, bool):
        return False
    if not all(key in row for key in ("tenant", "state", "owner", "fence", "lease_until")):
        return False

    row_fence = row["fence"]
    lease_until = row["lease_until"]
    if not isinstance(row_fence, int) or isinstance(row_fence, bool):
        return False
    if not isinstance(lease_until, int) or isinstance(lease_until, bool):
        return False

    return (
        row["state"] == "running"
        and row["tenant"] == tenant
        and row["owner"] == owner
        and row_fence == fence
        and lease_until > now
    )
